function formatBooking(booking: typeof bookingsTable.$inferSelect, courtName?: string) {
  return {
    ...booking,
    totalPrice: Number(booking.totalPrice),
    refundAmount: Number(booking.refundAmount ?? 0),
    pricePerSlot: booking.pricePerSlot != null ? Number(booking.pricePerSlot) : undefined,
    totalSlots: booking.totalSlots ?? undefined,
    splitInviteToken: booking.splitInviteToken ?? undefined,
    rentedItems: booking.rentedItems ?? undefined,
    courtName: courtName ?? undefined,
    stripeSessionId: booking.stripeSessionId ?? undefined,
    stripePaymentIntentId: booking.stripePaymentIntentId ?? undefined,
    stripeRefundId: booking.stripeRefundId ?? undefined,
    managementToken: booking.managementToken ?? undefined,
  };
}

router.get("/bookings", requireAuth, async (req, res): Promise<void> => {
  const params = ListBookingsQueryParams.safeParse(req.query);
  if (!params.success) {
    res.status(400).json({ error: params.error.message });
    return;
  }

  const userId = getCurrentUserId(req)!;
  const role = await getUserRole(userId);

  const conditions = [];
  if (params.data.courtId != null) {
    conditions.push(eq(bookingsTable.courtId, params.data.courtId));
  }
  if (params.data.status) {
    conditions.push(eq(bookingsTable.status, params.data.status));
  }
  if (params.data.customerEmail) {
    conditions.push(eq(bookingsTable.customerEmail, params.data.customerEmail));
  }

  let query = db
    .select({
      booking: bookingsTable,
      courtName: courtsTable.name,
    })
    .from(bookingsTable)
    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
    .$dynamic();

  if (role === "admin") {
    if (conditions.length > 0) {
      query = query.where(and(...conditions));
    }
  } else {
    // "My bookings" — always scoped to the authenticated booker, regardless of
    // role. Owners use GET /api/owner/bookings for the facility-wide view.
    conditions.push(eq(bookingsTable.bookerUserId, userId));

import { pgTable, text, serial, timestamp, numeric, integer, boolean } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod/v4";

export const bookingsTable = pgTable("bookings", {
  id: serial("id").primaryKey(),
  courtId: integer("court_id").notNull(),
  bookerUserId: text("booker_user_id"),
  customerName: text("customer_name").notNull(),
  customerEmail: text("customer_email").notNull(),
  customerPhone: text("customer_phone"),
  date: text("date").notNull(), // YYYY-MM-DD
  startTime: text("start_time").notNull(), // HH:MM
  endTime: text("end_time").notNull(), // HH:MM
  totalPrice: numeric("total_price", { precision: 10, scale: 2 }).notNull(),
  status: text("status").notNull().default("pending"), // pending | awaiting_players | confirmed | cancelled | blocked
  rentedItems: text("rented_items"),
  notes: text("notes"),
  stripeSessionId: text("stripe_session_id"),
  stripePaymentIntentId: text("stripe_payment_intent_id"),
  refundAmount: numeric("refund_amount", { precision: 10, scale: 2 }).notNull().default("0"),
  stripeRefundId: text("stripe_refund_id"),
  // Opaque token allowing a guest (no Clerk session) to view & cancel their booking.
  managementToken: text("management_token").unique(),
  // Split payment fields
  isSplit: boolean("is_split").notNull().default(false),
  totalSlots: integer("total_slots"),
  pricePerSlot: numeric("price_per_slot", { precision: 10, scale: 2 }),
  splitInviteToken: text("split_invite_token").unique(),
  // Smart lock access code (delivered post-payment)
  accessCode: text("access_code"),
  // Recurring booking group (null = one-off, uuid string = part of a weekly series)
  recurringGroupId: text("recurring_group_id"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export const insertBookingSchema = createInsertSchema(bookingsTable).omit({ id: true, createdAt: true });
export type InsertBooking = z.infer<typeof insertBookingSchema>;
export type Booking = typeof bookingsTable.$inferSelect;

